import json, math, statistics
facts = {'USERF1': {'value': 3780.0, 'unit': 'scf'}, 'USERF2': {'value': 135.0, 'unit': 'stb'}}
values = [facts['USERF1']['value'], facts['USERF2']['value']]
by_case = {}
by_case['default'] = [facts['USERF1']['value'], facts['USERF2']['value']]
scores = {key: values[0] for key, values in by_case.items() if len(values) == 1}
leaders = sorted(key for key, value in scores.items() if math.isclose(value, max(scores.values()), rel_tol=1e-9, abs_tol=1e-12)) if scores else []
rank_groups = []
for key in sorted(scores, key=lambda item: (-scores[item], item)):
    if rank_groups and math.isclose(scores[key], scores[rank_groups[-1][0]], rel_tol=1e-9, abs_tol=1e-12):
        rank_groups[-1].append(key)
    else:
        rank_groups.append([key])
ranking = ['='.join(sorted(group)) for group in rank_groups]
outputs = {}
selected = values
outputs['OUT_ratio'] = {'value': selected[0] / selected[1], 'unit': 'scf/stb'}
with open('analysis_001.json', 'w') as output:
    json.dump({'contract_id': 'CC-V7', 'outputs': outputs, 'used_input_ids': ['USERF1', 'USERF2'], 'used_formula_id': None, 'summary': 'Generic calculation from verified inputs.'}, output)

